import numpy as np

def simulate_step(grid):
    N = grid.shape[0]
    new_grid = grid.copy()
    changes_made = False

    # Iterate over all possible 2x2 squares
    for r in range(N - 1):
        for c in range(N - 1):
            # Extract the 2x2 square
            subgrid = grid[r:r+2, c:c+2]
            infected_count = np.sum(subgrid)

            # Rule 1: Three infected -> last sterile gets infected
            if infected_count == 3:
                # Find the sterile cell in the 2x2 area
                sterile_coords = []
                for ir in range(2):
                    for ic in range(2):
                        if subgrid[ir, ic] == 0:
                            sterile_coords.append((r + ir, c + ic))

                if sterile_coords:
                    # Only one sterile cell must exist if count is 3
                    sr, sc = sterile_coords[0]
                    if new_grid[sr, sc] == 0:
                        new_grid[sr, sc] = 1
                        changes_made = True

            # Rule 2: Two infected -> mutation (flip)
            elif infected_count == 2:
                # Flip all 4 cells in the 2x2 area
                for ir in range(2):
                    for ic in range(2):
                        sr, sc = r + ir, c + ic
                        if new_grid[sr, sc] == 1:
                            new_grid[sr, sc] = 0
                        else:
                            new_grid[sr, sc] = 1
                changes_made = True

    return new_grid, changes_made

def run_simulation(initial_grid, max_steps=200):
    grid = initial_grid.copy()
    history = []
    for step in range(max_steps):
        new_grid, changed = simulate_step(grid)
        grid = new_grid
        history.append(grid.copy())

        # Check for stabilization or full infection
        if not changed:
            # Stabilized
            return grid, "Stabilized", step + 1

        if np.sum(grid) == 25:
            # Fully infected
            return grid, "Full Infection", step + 1

    # Reached max steps without completion
    return grid, "Max Steps Reached", max_steps

